<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderOidcScopesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderOidcScopesAccessor trait.
 *
 * Covers null default, string/VO assignment via withOidcScopes,
 * getOidcScopes/oidcScopes accessors, and isOidcScopesChanged with/without original.
 */
class TenantLoginProviderOidcScopesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withOidcScopes creates a new instance with the OidcScopes set
     * from a string value, and getOidcScopes returns the primitive string.
     */
    public function testWithOidcScopesFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderOidcScopesAccessorUnitTest();

        // Act
        $result = $holder->withOidcScopes('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getOidcScopes());
    }
    /**
     * Asserts that withoidcScopes has access to the value object
     * from a string value, and getOidcScopes returns the primitive string.
     */
    public function testWithOidcScopesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderOidcScopesAccessorUnitTest();

        // Act
        $result = $holder->withOidcScopes('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->oidcScopes()->value());
    }
    public function testChangedOidcScopes(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderOidcScopesAccessorUnitTest();
        $original = $holder->withOidcScopes('one');
        $same = $holder->withOidcScopes('one');
        $modified = $holder->withOidcScopes('other');

        // Act
        $unchanged = $holder->isOidcScopesChanged();
        $withSame = $original->isOidcScopesChanged($same);
        $withDiferent = $original->isOidcScopesChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderOidcScopesAccessorUnitTest
{
    use TenantLoginProviderOidcScopesAccessor;
}
